import{_ as t,o as a,c as r,a2 as s}from"./chunks/framework.Cu3jFwFD.js";const u=JSON.parse('{"title":"Hazards","description":"","frontmatter":{},"headers":[],"relativePath":"features/hazards/design.md","filePath":"features/hazards/design.md","lastUpdated":1794908281000}'),i={name:"features/hazards/design.md"};function d(n,e,o,l,h,c){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="hazards" tabindex="-1">Hazards <a class="header-anchor" href="#hazards" aria-label="Permalink to &quot;Hazards&quot;">​</a></h1><p><strong>Status:</strong> <span class="status-badge status-designed">DESIGNED</span> · <strong>Updated:</strong> 2026-11-17 · <a href="./../../GDD">GDD</a></p><p>The catalogue of everything on the map that can hurt the van. Each hazard is a self-contained module: what it is, how it warns, what it does, what counters it, and its numbers. Other specs only decide <strong>when and where</strong> a hazard appears (the trial&#39;s danger in <a href="./../trials/design">trials</a>, the overtime storm in <a href="./../day-cycle-and-storm/design">day-cycle-and-storm</a>) and refer to it by its id. Serves <strong>Push your luck</strong>: every hazard is telegraphed, so getting hit is the price of a choice, not bad luck (<a class="decision-ref" href="/hex-gdd/GDD#d-080">D‑080</a>).</p><h2 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Rules&quot;">​</a></h2><ol><li><strong>Module shape.</strong> Every hazard defines: id, source (who spawns it), telegraph, effect, counters, numbers. A new hazard is added as a new module here; schedulers only reference its id.</li><li><strong>Readability with the chase camera</strong> (<a class="decision-ref" href="/hex-gdd/GDD#d-077">D‑077</a>): every telegraph is visible from behind the van at speed: a ground ring plus a vertical light column, so a warning ahead of the van or partly behind buildings is still seen.</li><li>Hit grace: after any hazard damages the van, no hazard can damage it again for 1 s.</li><li>Pausing freezes every telegraph and timer.</li></ol><h3 id="strike-lightning-strike" tabindex="-1"><code>strike</code>: lightning strike <a class="header-anchor" href="#strike-lightning-strike" aria-label="Permalink to &quot;`strike`: lightning strike&quot;">​</a></h3><ul><li><strong>Source:</strong> shift lightning (trial danger) and the overtime storm.</li><li><strong>Telegraph:</strong> a ground ring that fills over the warning time, with a thin light column.</li><li><strong>Effect:</strong> at the end of the warning, the strike hits everything within the hit radius of its point. The van loses 2 HP (<a class="decision-ref" href="/hex-gdd/GDD#d-064">D‑064</a>).</li><li><strong>Counters:</strong> drive out of the ring; Zeus&#39;s ward turns it away; the lightning shield absorbs one (<a href="./../upgrades/design">upgrades</a>).</li></ul><h3 id="big-strike-big-violet-strike" tabindex="-1"><code>big-strike</code>: big violet strike <a class="header-anchor" href="#big-strike-big-violet-strike" aria-label="Permalink to &quot;`big-strike`: big violet strike&quot;">​</a></h3><ul><li><strong>Source:</strong> the overtime storm only.</li><li><strong>Telegraph:</strong> a wide violet ring and column that fill over 3.5 s.</li><li><strong>Effect:</strong> the van loses 5 HP if inside the radius when it lands.</li><li><strong>Counters:</strong> leave the circle; Zeus&#39;s ward; the lightning shield only with the Grounding Coil relic (<a class="decision-ref" href="/hex-gdd/GDD#d-053">D‑053</a>).</li></ul><h3 id="boundary-zeus-s-wrath-at-the-map-edge" tabindex="-1"><code>boundary</code>: Zeus&#39;s wrath at the map edge <a class="header-anchor" href="#boundary-zeus-s-wrath-at-the-map-edge" aria-label="Permalink to &quot;`boundary`: Zeus&#39;s wrath at the map edge&quot;">​</a></h3><ul><li><strong>Source:</strong> the van drives more than the boundary margin past the outermost road.</li><li><strong>Telegraph:</strong> a warning banner with a countdown on screen.</li><li><strong>Effect:</strong> at 0 the van is wrecked outright (the day fails, see <a href="./../damage-and-repair/design">damage-and-repair</a>).</li><li><strong>Counters:</strong> drive back inside; the countdown resets. Ward and shield do not help.</li></ul><h3 id="crash-collisions" tabindex="-1"><code>crash</code>: collisions <a class="header-anchor" href="#crash-collisions" aria-label="Permalink to &quot;`crash`: collisions&quot;">​</a></h3><ul><li><strong>Source:</strong> buildings, props, traffic and anything solid.</li><li><strong>Telegraph:</strong> none (the world itself).</li><li><strong>Effect:</strong> an impact of 12 m/s or more costs 1 HP; an impact between 4 and 12 m/s is a bump and costs 0.5 HP; below 4 m/s nothing. The first 2.5 s of a day are free (the van drops onto the road).</li><li><strong>Counters:</strong> drive cleanly; the Soft / Steel Bumper cards only lower repair cost.</li></ul><h2 id="numbers" tabindex="-1">Numbers <a class="header-anchor" href="#numbers" aria-label="Permalink to &quot;Numbers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Name</th><th>Value</th><th>Unit</th><th>What to watch in playtests</th></tr></thead><tbody><tr><td><code>strike</code> warning time</td><td>0.65–1.7 <mark class="tune">TUNE</mark></td><td>s</td><td>Readable from the chase camera at speed</td></tr><tr><td><code>strike</code> hit radius</td><td>1.2 <mark class="tune">TUNE</mark></td><td>m</td><td></td></tr><tr><td><code>strike</code> damage</td><td>2 (<a class="decision-ref" href="/hex-gdd/GDD#d-064">D‑064</a>)</td><td>HP</td><td></td></tr><tr><td><code>big-strike</code> radius / warning</td><td>9 / 3.5 <mark class="tune">TUNE</mark></td><td>m / s</td><td></td></tr><tr><td><code>big-strike</code> damage</td><td>5 <mark class="tune">TUNE</mark></td><td>HP</td><td></td></tr><tr><td><code>boundary</code> margin / countdown</td><td>60 / 5 <mark class="tune">TUNE</mark></td><td>m / s</td><td></td></tr><tr><td><code>crash</code> damage: crash (≥ 12 m/s) / bump (4–12 m/s)</td><td>1 / 0.5 <mark class="tune">TUNE</mark></td><td>HP</td><td>Crashes per day in a normal run</td></tr><tr><td><code>crash</code> grace at day start</td><td>2.5</td><td>s</td><td></td></tr><tr><td>Hit grace after any damage</td><td>1</td><td>s</td><td></td></tr></tbody></table><h2 id="edge-cases" tabindex="-1">Edge cases <a class="header-anchor" href="#edge-cases" aria-label="Permalink to &quot;Edge cases&quot;">​</a></h2><ul><li>Two strikes landing in the same 1 s grace window cost HP only once.</li><li>A strike landing on HQ while the van is parked there in overtime does not happen: the storm pauses at HQ (<a href="./../day-cycle-and-storm/design">day-cycle-and-storm</a>).</li><li>A failed Chance (scam) delivery also costs HP but is not a hazard; it lives in <a href="./../packages/design">packages</a>.</li></ul><h2 id="open-questions" tabindex="-1">Open questions <a class="header-anchor" href="#open-questions" aria-label="Permalink to &quot;Open questions&quot;">​</a></h2><ul><li>A third hazard type (old GDD question) can be added as a new module without changing the schedulers.</li></ul><h2 id="history" tabindex="-1">History <a class="header-anchor" href="#history" aria-label="Permalink to &quot;History&quot;">​</a></h2><ul><li>2026-11-17: designed as a modular catalogue (<a class="decision-ref" href="/hex-gdd/GDD#d-080">D‑080</a>). Strike, big strike and boundary moved here from day-cycle-and-storm; crash amounts moved here from damage-and-repair.</li></ul>',21)])])}const m=t(i,[["render",d]]);export{u as __pageData,m as default};
